package cn.sishiyuni.core.data

import androidx.room.*

@Entity(tableName="sessions")
data class SessionEntity(@PrimaryKey val id:String,val title:String="新的悄悄话",val createdAt:Long=System.currentTimeMillis(),val updatedAt:Long=createdAt,val draft:String="",val archived:Boolean=false)
@Entity(tableName="messages",indices=[Index(value=["sessionId","ordinal"],unique=true),Index("sessionId"),Index("at")],foreignKeys=[ForeignKey(entity=SessionEntity::class,parentColumns=["id"],childColumns=["sessionId"],onDelete=ForeignKey.RESTRICT)])
data class MessageEntity(@PrimaryKey val id:String,val sessionId:String,val ordinal:Long,val who:String,val text:String,val at:Long=System.currentTimeMillis(),val source:String="model",val favorite:Boolean=false,val status:String="complete",val muted:Boolean=false,val raw:String="{}")
@Entity(tableName="plans",indices=[Index("date")])
data class PlanEntity(@PrimaryKey val id:String,val date:String,val text:String,val done:Boolean=false,val important:Boolean=false,val raw:String="{}")
@Entity(tableName="folders")
data class FolderEntity(@PrimaryKey val id:String,val name:String,val createdAt:Long=System.currentTimeMillis())
@Entity(tableName="memos",indices=[Index("folderId"),Index("updatedAt")])
data class MemoEntity(@PrimaryKey val id:String,val title:String="",val body:String="",val createdAt:Long=System.currentTimeMillis(),val updatedAt:Long=createdAt,val pinnedAt:Long?=null,val folderId:String?=null,val starred:Boolean=false,val deletedAt:Long?=null,val mood:String="",val revision:Long=0,val raw:String="{}")
@Entity(tableName="memory_facts",indices=[Index("sourceMessageId")])
data class FactEntity(@PrimaryKey val key:String,val value:String,val quote:String="",val sourceMessageId:String="",val updatedAt:Long=System.currentTimeMillis(),val locked:Boolean=false,val blocked:Boolean=false)
@Entity(tableName="memory_chapters",indices=[Index("sessionId")])
data class ChapterEntity(@PrimaryKey val id:String,val sessionId:String,val fromOrdinal:Long,val toOrdinal:Long,val fingerprint:String,val summary:String,val updatedAt:Long=System.currentTimeMillis())
@Entity(tableName="subjects")
data class SubjectEntity(@PrimaryKey val id:String,val name:String,val deleted:Boolean=false)
@Entity(tableName="focus_logs",indices=[Index("at")])
data class FocusLogEntity(@PrimaryKey val id:String,val at:Long,val minutes:Double,val title:String="",val group:String="",val kind:String="",val raw:String="{}")
@Entity(tableName="timers")
data class TimerEntity(@PrimaryKey val id:String="countdown",val kind:String="countdown",val label:String="休息一下",val durationMs:Long=0,val remainingMs:Long=0,val elapsedDeadline:Long=0,val wallDeadline:Long=0,val bootCount:Int=0,val running:Boolean=false,val completed:Boolean=false,val startedWall:Long=0,val generation:String="",val raw:String="{}")
@Entity(tableName="skills")
data class SkillEntity(@PrimaryKey val id:String,val name:String,val description:String,val content:String,val source:String,val digest:String,val enabled:Boolean=false,val installedAt:Long=System.currentTimeMillis(),val files:String="[]")
@Entity(tableName="records",primaryKeys=["kind","id"],indices=[Index("kind")])
data class RecordEntity(val kind:String,val id:String,val payload:String,val updatedAt:Long=System.currentTimeMillis())
@Entity(tableName="imports")
data class ImportEntity(@PrimaryKey val digest:String,val original:String,val importedAt:Long=System.currentTimeMillis(),val report:String)
